original_checker='"""Independent complete literal economics and actual production cash fixtures."""\nimport io, contextlib\n_buffer=io.StringIO()\nwith contextlib.redirect_stdout(_buffer):\n    exec(compile(\'#!/usr/bin/env python3\\n"""Independent literal arithmetic: no import of model, no read of its inputs/output.\\nFor base and rent sensitivity the requested payouts have no statutory/cash binding limits;\\nthis independently computes economic aggregate recurrence, not merely re-runs production code.\\n"""\\nimport json\\n\\ndef calc(rent):\\n    cash=6.86847813114+21.29221120543-.22091848888-.54238221870\\n    prior_income=9.;prior_sales=34.17573992158;rows=[]\\n    sales=[33.3,33.55,34.7,36.15,37.2]\\n    margins=[.275,.28,.285,.29,.292]\\n    costs=[2.5,2.8,2.6,2,1.5];amort=[.5,.6,.7,.8,.85];extra=[.7,.6,.2,.1,0]\\n    for t in range(1,961):\\n        opening=cash\\n        if t<6:\\n            R=sales[t-1];M=margins[t-1];I=costs[t-1];D=amort[t-1];W=.15*(R-prior_sales)+extra[t-1]\\n        else:\\n            inc=[.035,.03,.025,.02,.015][t-6] if t<11 else .015\\n            R=prior_sales*(1+inc);M=.29+.002*max(0,(10-t)/5)\\n            D=.85*R/37.2;I=D+.20*max(0,R-prior_sales);W=.15*(R-prior_sales)\\n        earnings=R*M-(rent-.4)*R/33.3*.75+opening*.009\\n        F=earnings+D-I-W\\n        keep=max(3,.15*R)\\n        ordinary=.65*prior_income if t<6 else .85*earnings\\n        if t>10:ordinary=max(0,F-.15*(R-prior_sales))\\n        dividend=ordinary+(.2*max(0,opening-keep) if t>=6 else 0)\\n        cash=opening+F-dividend\\n        rows.append({\\\'year\\\':t,\\\'sales\\\':R,\\\'profit\\\':earnings,\\\'FCF\\\':F,\\\'dividend\\\':dividend,\\\'cash\\\':cash})\\n        prior_income=earnings;prior_sales=R\\n    vals={}\\n    for rate in [.09,.095,.10]:\\n        terminal=rows[-1][\\\'dividend\\\']*1.015/(rate-.015)\\n        value=sum(z[\\\'dividend\\\']/(1+rate)**z[\\\'year\\\'] for z in rows)+terminal/(1+rate)**960\\n        y5=sum(z[\\\'dividend\\\']/(1+rate)**(z[\\\'year\\\']-5) for z in rows[5:])+terminal/(1+rate)**955\\n        vals[str(rate)]={\\\'value_per_share\\\':value/1.219964222,\\\'year5_per_share\\\':y5/1.219964222}\\n    return {\\\'first_five\\\':rows[:5],\\\'last\\\':rows[-1],\\\'values\\\':vals}\\ndef independent_ri(high):\\n    R5=[33.8,34.7,35.4,36.,36.6] if high else [33.8,34.,34.,34.,34.]\\n    M5=[.275,.28,.285,.29,.29] if high else [.275]*5\\n    growth=.015 if high else .01; rate=.09 if high else .10\\n    cash=27.39738862899;book=39.99380201652;old_sales=34.17573992158;old_profit=9.;residual_pv=0.;div_pv=0.\\n    first=[]\\n    for year in range(1,961):\\n        opening_book=book;opening_cash=cash\\n        if year<=5:\\n            sales=R5[year-1];margin=M5[year-1]\\n            invest=[2.5,2.8,2.6,2.,1.5][year-1];depreciation=[.5,.6,.7,.8,.85][year-1]\\n            wc=.15*(sales-old_sales)+[.7,.6,.2,.1,0][year-1]\\n        else:\\n            sales=old_sales*(1+growth);margin=M5[-1]\\n            depreciation=.85*sales/R5[-1];invest=depreciation+.20*(sales-old_sales);wc=.15*(sales-old_sales)\\n        profit=sales*margin+.009*opening_cash;fcf=profit+depreciation-invest-wc\\n        minimum=max(3,.15*sales)\\n        dividend=(.65*old_profit if year<=5 else .85*profit)\\n        if year>10:dividend=max(0,fcf-.15*(sales-old_sales))\\n        if year>=6:dividend+=.20*max(0,opening_cash-minimum)\\n        cash+=fcf-dividend;book+=profit-dividend\\n        residual_pv+=(profit-rate*opening_book)/(1+rate)**year\\n        div_pv+=dividend/(1+rate)**year\\n        if year<=5:first.append(dict(year=year,profit=profit,dividend=dividend,cash=cash,book=book))\\n        old_sales=sales;old_profit=profit\\n    terminal=dividend*(1+growth)/(rate-growth)\\n    ri=39.99380201652+residual_pv+(terminal-book)/(1+rate)**960\\n    return dict(value_per_share=ri/1.219964222,residual_pv=residual_pv,first_five=first,\\n      ddm_identity=(div_pv+terminal/(1+rate)**960)/1.219964222)\\nprint(json.dumps({\\\'base\\\':calc(.4),\\\'rent_stress\\\':calc(.65),\\\'formal_auxiliary_low\\\':independent_ri(False),\\n  \\\'formal_auxiliary_high\\\':independent_ri(True)},sort_keys=True,separators=(\\\',\\\',\\\':\\\')))\\n\', __file__, "exec"), {"__file__":__file__,"__name__":"__main__"})\nprint(_buffer.getvalue())\nexec(compile("from pathlib import Path\\nfrom decimal import Decimal as D\\nimport json,hashlib,importlib.util\\np=Path(__file__).resolve().parent;o=json.loads((p/\'2026-Q3-output.json\').read_text());lit=json.loads(_AUTHOR_JSON)\\nfor n,key in [(\'base\',\'base\'),(\'rent_stress\',\'rent_cost_stress\')]:\\n a=lit[n];s=o[\'scenarios\'][key]\\n for r,k in [(\'0.09\',\'value_9pct\'),(\'0.095\',\'value_95pct\'),(\'0.1\',\'value_10pct\')]:assert abs(a[\'values\'][r][\'value_per_share\']-s[k][\'per_share\'])<1e-9\\n for x,z in zip(a[\'first_five\'],s[\'rows\'][:5]):\\n  assert abs(x[\'dividend\']-z[\'holder_cash\'])<1e-10 and abs(x[\'cash\']-z[\'closing\'][\'cash\'])<1e-10\\nfor a in o[\'formal_auxiliary_residual_income\']:\\n b=lit[\'formal_auxiliary_\'+a[\'name\']];assert abs(a[\'valuation\'][\'value_per_share\']-b[\'value_per_share\'])<1e-9\\n assert abs(b[\'ddm_identity\']-b[\'value_per_share\'])<1e-9\\nbase=o[\'scenarios\'][\'base\'];op=D(\'33.3\')*D(\'.275\');assert abs(float(op)-base[\'rows\'][0][\'operating_common_profit_after_rent\'])<1e-12\\nassert abs(o[\'scenarios\'][\'rent_cost_stress\'][\'rows\'][0][\'operating_common_profit_after_rent\']-(float(op)-.25*.75))<1e-12\\nmax_error=0\\nallpaths=[(n,z[\'rows\']) for n,z in o[\'scenarios\'].items()]+[(\'aux_\'+z[\'name\'],z[\'rows\']) for z in o[\'formal_auxiliary_residual_income\']]\\nfor n,rows in allpaths:\\n assert len(rows)==960\\n for a in rows:\\n  b=a[\'opening\'];s=a[\'closing\'];scale=max(1,a[\'revenue\'])\\n  identities=[(s[\'cash\'],b[\'cash\']+a[\'common_free_cash\']-a[\'holder_cash\']),(s[\'equity\'],b[\'equity\']+a[\'common_profit\']-a[\'holder_cash\']), (s[\'equity\'],s[\'cash\']+s[\'net_operating_capital\']), (s[\'parent_re\'],b[\'parent_re\']+a[\'parent_legal_profit\']-a[\'parent_reserve_added\']-a[\'holder_cash\']), (s[\'sub_re\'],b[\'sub_re\']+a[\'sub_profit\']-a[\'sub_reserve_added\']-a[\'sub_dividend_declared\']), (s[\'dividend_receivable\'],b[\'dividend_receivable\']+a[\'sub_dividend_declared\']-a[\'sub_dividend_received\']), (s[\'pool_payable\'],b[\'pool_payable\']-a[\'old_pool_liability_repaid\'])]\\n  for x,y in identities:\\n   err=abs(x-y)/scale;max_error=max(max_error,err);assert err<1e-12\\n  assert abs(s[\'dividend_receivable\']-s[\'dividend_payable\'])<1e-8\\n  assert abs(s[\'dividend_payable\']-sum(v for t,v in s[\'due\']))/scale<1e-12\\n  assert all(t>a[\'year\'] for t,v in s[\'due\'] if v>1e-8)\\n  assert (s[\'sub_cash\']-.3*a[\'required_cash\']-s[\'dividend_payable\'])/scale>=-1e-12\\n  assert a[\'sub_dividend_declared\']<=a[\'sub_declaration_cash_capacity\']+1e-8\\n  assert s[\'parent_capital_surplus\']==b[\'parent_capital_surplus\']\\n  assert s[\'lease\']==b[\'lease\']-a[\'lease_principal_within_rent\']+a[\'new_lease_noncash\']\\n  for who in [\'parent\',\'sub\']:\\n   income=a[\'parent_legal_profit\'] if who==\'parent\' else a[\'sub_profit\']\\n   app=min(max(0,.5*b[who+\'_capital\']-b[who+\'_reserve\']),.1*max(0,income-max(0,-b[who+\'_re\'])))\\n   assert abs(app-a[who+\'_reserve_added\'])<1e-8\\n for field in [\'trade_receivable\',\'pool_payable\']:assert abs(rows[-1][\'closing\'][field])<1e-8\\nassert o[\'year5_full_shared_state\']==base[\'rows\'][4][\'closing\']\\nfor r,k in [(.09,\'high\'),(.10,\'low\')]:\\n y5=sum(a[\'holder_per_share\']/(1+r)**(a[\'year\']-5) for a in base[\'rows\'][5:]);assert abs(y5-o[\'return_model\'][\'base_case_terminal_equity_value_range_per_share\'][\'year_5\'][k])<1e-6\\nspec=importlib.util.spec_from_file_location(\'fenjiu\',p/\'2026-Q3.py\');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)\\na=m.legal_step(-4,0,10,10,100,100);assert abs(a[\'dividend\']-5.4)<1e-12 and abs(a[\'appropriation\']-.6)<1e-12\\nb=m.legal_step(0,4.8,10,10,100,100);assert abs(b[\'dividend\']-9.8)<1e-12\\nc=m.legal_step(0,5,10,10,100,3);assert c[\'dividend\']==3 and c[\'reserve\']==5\\nprint(json.dumps({\'fresh_literal_main_rent_and_independent_aux\':\'passed\',\'own_Y1_operating_earnings\':str(op),\'all16paths960annual_cash_equity_legal_lease_and_funded_declared_receivables\':\'passed\',\'max_revenue_scaled_identity_error\':max_error,\'same_base5_terminal\':\'passed\',\'actual_production_loss_first_cap_cash_fixtures\':\'passed\'},indent=2))\\n", __file__, "exec"), {"__file__":__file__,"__name__":"__main__","_AUTHOR_JSON":_buffer.getvalue()})\n'
with tempfile.TemporaryDirectory(prefix='q3-lossless-full-')as tmp:
    target=Path(tmp);source=here/'2026-Q3-output.json';raw=target/'2026-Q3-output.json'
